return {api_version=1,id="EX1_558",name="Harrison Jones",text="<b>Battlecry:</b> Destroy your opponent's weapon and draw cards equal to its Durability.",set="EXPERT1",type="minion",rarity="legendary",cost=5,attack=5,health=4,keywords={"battlecry"},on_battlecry=function(ctx,self)local p=ctx:opponent(ctx:controller(self));local w=ctx:player(p).weapon;if w then local n=ctx:entity(w).health;ctx:destroy(w);ctx:draw(ctx:controller(self),n)end end}
